python3 -c "
import urllib.request
# Try getting UK Pound historical rates from FRED
url = 'https://fred.stlouisfed.org/graph/fredgraph.csv?id=DEXUSEU'
try:
    with urllib.request.urlopen(url, timeout=15) as response:
        lines = response.read().decode('utf-8').split('\n')
        for line in lines:
            if '2002' in line:
                print(line)
except Exception as e:
    print(f'Error: {e}')

# Also check DEXUKUS (this is the other direction - British Pounds per US Dollar)
print('Trying DEXUKUS:')
url2 = 'https://fred.stlouisfed.org/graph/fredgraph.csv?id=DEXUKUS'
try:
    with urllib.request.urlopen(url2, timeout=15) as response:
        lines = response.read().decode('utf-8').split('\n')
        for line in lines:
            if '2002' in line:
                print(line)
except Exception as e:
    print(f'Error: {e}')
"

